        ('RESERVE_FIN_S = 900        # l\'amorce cesse le travail et pousse ses traces 15 min avant l\'échéance (contre-lecture M-4)\nETIQUETTE = "bbis-t07-repetition-v1"\nCARTE = "A100 SXM4 80GB"   # forme de OFFRE.json, écrite par `offre-depuis-recherche`\n',
         'RESERVE_FIN_S = 900        # l\'amorce cesse le travail et pousse ses traces 15 min avant l\'échéance (contre-lecture M-4)\nETIQUETTE = "bbis-t07-repetition-v4"\nCARTE = "A100 SXM4 80GB"   # forme de OFFRE.json, écrite par `offre-depuis-recherche`\n', 1),
        ('\ndef jouer_carte(sortie: Path, appareil: str = "cuda", n_actions: int = ACTIONS, largeur: int = LARGEUR, par_famille: int = 3,\n',
         '\nSEUIL_SANS_NOEUD = 1e-5        # règle de lecture de la passe (brouillon 6, plan, point 5 ; m8)\n\n\ndef _lots_egaux(a, b) -> bool:\n    """Deux constructions du lot (jetons réduits, moyenne, écart type, indices) égales au bit près."""\n    import numpy as np\n    import torch\n    return bool(torch.equal(a.X, b.X) and torch.equal(a.idx, b.idx) and np.array_equal(a.mu, b.mu) and np.array_equal(a.s, b.s))\n\n\ndef _memoire_carte(appareil: str):\n    import torch\n    return int(torch.cuda.max_memory_allocated()) if str(appareil).startswith("cuda") and torch.cuda.is_available() else None\n\n\ndef lecture_de_la_passe(doc: dict, tolerance: float = 1e-4) -> dict:\n    """Règle écrite avant la passe : compte si chaque famille porte un écart numérique ≤ 10⁻⁴ et l\'égalité au bit près\n    (déterminisme des deux familles, de l\'attention du contrôle, lot reconstruit égal au premier) ; puis ≤ 10⁻⁵ pour chaque famille :\n    « la course part sans nœud » ; sinon « nœud écrit à la mère avant la course »."""\n    import math\n    c = doc.get("controle_carte_processeur") or {}\n    ecarts = {}\n    for f in ("lineaire", "attention"):\n        e = (c.get(f) or {}).get("ecart_relatif_max") if isinstance(c.get(f), dict) else None\n        if isinstance(e, bool) or not isinstance(e, (int, float)) or not math.isfinite(e):\n            return {"compte": False, "motif": f"écart de « {f} » absent ou non numérique ({e!r})", "ecarts": ecarts}\n        ecarts[f] = float(e)\n    egal = (all((doc.get("deterministe") or {}).get(f) is True for f in ("lineaire", "attention"))\n            and (c.get("determinisme_attention") or {}).get("egal_au_bit") is True\n            and (doc.get("lot_reconstruit") or {}).get("egal_au_premier") is True)\n    if not egal:\n        return {"compte": False, "motif": "égalité au bit près absente ou fausse", "ecarts": ecarts}\n    if not max(ecarts.values()) <= float(tolerance):\n        return {"compte": False, "motif": f"écart au-dessus de {tolerance:g} : {ecarts}", "ecarts": ecarts}\n    sans_noeud = max(ecarts.values()) <= SEUIL_SANS_NOEUD\n    return {"compte": True, "ecarts": ecarts, "seuil_sans_noeud": SEUIL_SANS_NOEUD,\n            "issue": "la course part sans nœud" if sans_noeud else\n                     "nœud écrit à la mère avant la course (écart entre 10⁻⁵ et 10⁻⁴)"}\n\n\ndef jouer_carte(sortie: Path, appareil: str = "cuda", n_actions: int = ACTIONS, largeur: int = LARGEUR, par_famille: int = 3,\n', 1),
        ('        from controle_ia.t07bbis import apprentissage_carte_v1 as ac\n        from controle_ia.t07bbis import validation_imbriquee_v2 as vi\n        from controle_ia.t07bbis.commun_v1 import (COUCHES_REELLES, FAMILLES, L2, N_ACTIONS_CONTROLE_CARTE, N_PLIS_INTERNES,\n',
         '        from controle_ia.t07bbis import apprentissage_carte_v1 as ac\n        from controle_ia.t07bbis import validation_imbriquee_v3 as vi\n        from controle_ia.t07bbis.commun_v1 import (COUCHES_REELLES, FAMILLES, L2, N_ACTIONS_CONTROLE_CARTE, N_PLIS_INTERNES,\n', 1),
        ('            return int(_graine(f"bbis/repetition/sonde/{f}/{l2_c}").generate_state(1)[0])\n        try:                                               # la fonction de la course v2, telle quelle\n            c = vi.controle_deux_horizons(lot, seqs, y, COUCHE, l2_c, graine_de, ctrl, familles=FAMILLES,\n                                          sondes_300={f: s for f, (r, g, s) in sondes.items() if r["l2"] == l2_c},\n',
         '            return int(_graine(f"bbis/repetition/sonde/{f}/{l2_c}").generate_state(1)[0])\n        try:                                               # la fonction de la course v3, telle quelle, sur un lot neuf\n            lot_controle = ac.LotCarte(seqs, appareil)     # comme la course : premier lot contre lot reconstruit (m1)\n            doc["lot_reconstruit"] = {"egal_au_premier": bool(_lots_egaux(lot, lot_controle))}\n            c = vi.controle_deux_horizons(lot_controle, seqs, y, COUCHE, l2_c, graine_de, ctrl, familles=FAMILLES,\n                                          sondes_300={f: s for f, (r, g, s) in sondes.items() if r["l2"] == l2_c},\n', 1),
        ('        doc["controle_parametres"]["duree_s"] = time.perf_counter() - t0\n        if not all(doc["deterministe"].values()):\n            return ecrire("controle", CODES["controle"], f"apprentissage non déterministe : {doc[\'deterministe\']}")\n    except Exception as e:                                         # torch compris : arrêt écrit, code fermé\n',
         '        doc["controle_parametres"]["duree_s"] = time.perf_counter() - t0\n        doc["controle_parametres"]["memoire_carte_max_octets"] = _memoire_carte(appareil)\n        if not all(doc["deterministe"].values()):\n            return ecrire("controle", CODES["controle"], f"apprentissage non déterministe : {doc[\'deterministe\']}")\n        doc["lecture_de_la_passe"] = lecture_de_la_passe(doc, tol)\n        if not doc["lecture_de_la_passe"]["compte"]:\n            return ecrire("controle", CODES["controle"], f"la passe ne compte pas : {doc[\'lecture_de_la_passe\'][\'motif\']}")\n    except Exception as e:                                         # torch compris : arrêt écrit, code fermé\n', 1),
